(function(){
    try {
        function findInShadows(selector) {
            let el = document.querySelector(selector);
            if (el) return el;
            const all = document.querySelectorAll('*');
            for (const el of all) {
                if (el.shadowRoot) {
                    const found = el.shadowRoot.querySelector(selector);
                    if (found) return found;
                }
            }
            return null;
        }

        const nameInput = findInShadows('#field-name');
        const addressInput = findInShadows('#field-address');
        const cityInput = findInShadows('#field-city');
        const zipInput = findInShadows('#field-zip');
        const cardInput = findInShadows('#field-card');
        const expiryInput = findInShadows('#field-expiry');
        const cvvInput = findInShadows('#field-cvv');
        const placeOrderBtn = document.querySelector('#place-order-btn') || findInShadows('#place-order-btn');

        if (nameInput) { nameInput.value = 'Jane Smith'; nameInput.dispatchEvent(new Event('input', {bubbles: true})); }
        if (addressInput) { addressInput.value = '123 Test Lane'; addressInput.dispatchEvent(new Event('input', {bubbles: true})); }
        if (cityInput) { cityInput.value = 'Anytown'; cityInput.dispatchEvent(new Event('input', {bubbles: true})); }
        if (zipInput) { zipInput.value = '00000'; zipInput.dispatchEvent(new Event('input', {bubbles: true})); }
        if (cardInput) { cardInput.value = '4111111111111111'; cardInput.dispatchEvent(new Event('input', {bubbles: true})); }
        if (expiryInput) { expiryInput.value = '12/28'; expiryInput.dispatchEvent(new Event('input', {bubbles: true})); }
        if (cvvInput) { cvvInput.value = '123'; cvvInput.dispatchEvent(new Event('input', {bubbles: true})); }

        if (placeOrderBtn) {
            placeOrderBtn.click();
            return 'Filled form and clicked place order!';
        }
        return 'Form filled, but button not found.';
    } catch(e) {
        return 'Error: ' + e.message;
    }
})()
